def render_header(targets: List[Path], is_system_scan: bool) ->Text:
    version = get_safety_version()
    now = datetime.datetime.now(datetime.timezone.utc)
    timestamp = now.strftime("%Y-%m-%d %H:%M:%S %Z")

    if is_system_scan:
        header_text = f"Safety {version} running system scan\n{timestamp}"
    else:
        if targets:
            target_paths = ", ".join([t.as_posix() for t in targets])
            header_text = f"Safety {version} scanning {target_paths}\n{timestamp}"
        else:
            header_text = f"Safety {version} scanning \n{timestamp}"

    return Text(header_text)

def print_header(console, targets: List[Path], is_system_scan: bool=False
    ) ->None:
    header = render_header(targets, is_system_scan)
    console.print(header)
